def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    if n == 0:
        return 1

    width = len(alphabet)
    char_id = {ch: i for i, ch in enumerate(alphabet)}

    go = [[-1] * width]
    bad = [False]

    for word in banned:
        node = 0
        for ch in word:
            c = char_id[ch]
            if go[node][c] < 0:
                go[node][c] = len(go)
                go.append([-1] * width)
                bad.append(False)
            node = go[node][c]
        bad[node] = True

    nodes = len(go)
    fail = [0] * nodes
    from collections import deque
    queue = deque()

    for c in range(width):
        child = go[0][c]
        if child < 0:
            go[0][c] = 0
        else:
            queue.append(child)

    while queue:
        node = queue.popleft()
        if bad[fail[node]]:
            bad[node] = True
        parent_fail = fail[node]
        for c in range(width):
            child = go[node][c]
            if child < 0:
                go[node][c] = go[parent_fail][c]
            else:
                fail[child] = go[parent_fail][c]
                queue.append(child)

    good = [node for node in range(nodes) if not bad[node]]
    pos = [-1] * nodes
    for i, node in enumerate(good):
        pos[node] = i

    size = len(good)
    trans = [[0] * size for _ in range(size)]
    for node in good:
        row = trans[pos[node]]
        for c in range(width):
            dest = pos[go[node][c]]
            if dest >= 0:
                row[dest] += 1

    def multiply(left, right):
        out = [[0] * size for _ in range(size)]
        for i in range(size):
            left_row = left[i]
            out_row = out[i]
            for k in range(size):
                factor = left_row[k]
                if factor:
                    right_row = right[k]
                    for j in range(size):
                        out_row[j] = (out_row[j] + factor * right_row[j]) % MOD
        return out

    result = [[1 if i == j else 0 for j in range(size)] for i in range(size)]
    exponent = n
    while exponent:
        if exponent & 1:
            result = multiply(result, trans)
        trans = multiply(trans, trans)
        exponent >>= 1

    return sum(result[0]) % MOD
